// Query syntax shines for joins + lets:
var q = from o in orders
        let total = o.Lines.Sum(l => l.Qty * l.Price)
        where total > 100
        join c in customers on o.CustomerId equals c.Id
        orderby total descending
        select new { c.Name, total };

